+    expect(render(template, { users: [1], title: "Team" })).toBe("yes Team");
+    expect(render(template, { users: [], title: "Team" })).toBe("none");
+    expect(render("{{#if value}}T{{else}}F{{/if}}", { value: Number.NaN })).toBe("T");
