+type Position = {
+  line: number;
+  column: number;
+};
+
+type TextNode = {
+  type: "text";
+  value: string;
+};
+
+type ValueNode = {
+  type: "value";
+  path: string;
+  escaped: boolean;
+  position: Position;
+};
+
+type BlockNode = {
+  type: "if" | "each";
+  path: string;
+  body: Node[];
+  alternate: Node[];
+  hasElse: boolean;
+  position: Position;
+};
+
+type Node = TextNode | ValueNode | BlockNode;
+
+type Frame = {
+  block: BlockNode;
+  parent: Node[];
+};
+
+type Context = {
+  root: unknown;
+  current: unknown;
+  index?: number;
+  inEach: boolean;
+};
+
+function templateError(message: string, position: Position): Error {
+  return new Error(`${message} at line ${position.line}, column ${position.column}`);
+}
+
+function positionAt(template: string, offset: number): Position {
+  let line = 1;
+  let column = 1;
+
+  for (let index = 0; index < offset; index++) {
+    if (template[index] === "\n") {
+      line++;
+      column = 1;
+    } else {
+      column++;
+    }
+  }
+
+  return { line, column };
+}
+
+function parse(template: string): Node[] {
+  const root: Node[] = [];
+  const stack: Frame[] = [];
+  let target = root;
+  let cursor = 0;
+
+  while (cursor < template.length) {
+    const open = template.indexOf("{{", cursor);
+    if (open === -1) {
+      target.push({ type: "text", value: template.slice(cursor) });
+      break;
+    }
+
+    if (open > cursor) {
+      target.push({ type: "text", value: template.slice(cursor, open) });
+    }
+
+    const triple = template.startsWith("{{{", open);
+    const closing = triple ? "}}}" : "}}";
+    const contentStart = open + (triple ? 3 : 2);
+    const close = template.indexOf(closing, contentStart);
+    const position = positionAt(template, open);
+
+    if (close === -1) {
+      throw templateError("Unclosed tag", position);
+    }
+
+    const content = template.slice(contentStart, close).trim();
+    cursor = close + closing.length;
+
+    if (triple) {
+      if (!content) {
+        throw templateError("Interpolation requires a path", position);
+      }
+      target.push({ type: "value", path: content, escaped: false, position });
+      continue;
+    }
+
+    if (content.startsWith("!")) {
+      continue;
+    }
+
+    if (content === "else") {
+      const frame = stack.at(-1);
+      if (!frame) {
+        throw templateError("'else' outside a block", position);
+      }
+      if (frame.block.hasElse) {
+        throw templateError("Duplicate 'else'", position);
+      }
+      frame.block.hasElse = true;
+      target = frame.block.alternate;
+      continue;
+    }
+
+    if (content.startsWith("#")) {
+      const match = /^#(\S+)(?:\s+(.+))?$/.exec(content);
+      const name = match?.[1] ?? "";
+      const path = match?.[2]?.trim() ?? "";
+      if (name !== "if" && name !== "each") {
+        throw templateError(`Unknown block '${name}'`, position);
+      }
+      if (!path) {
+        throw templateError(`Block '${name}' requires a path`, position);
+      }
+
+      const block: BlockNode = {
+        type: name,
+        path,
+        body: [],
+        alternate: [],
+        hasElse: false,
+        position,
+      };
+      target.push(block);
+      stack.push({ block, parent: target });
+      target = block.body;
+      continue;
+    }
+
+    if (content.startsWith("/")) {
+      const name = content.slice(1).trim();
+      const frame = stack.at(-1);
+      if (!frame) {
+        throw templateError(`Closing '${name}' without an open block`, position);
+      }
+      if (name !== frame.block.type) {
+        throw templateError(
+          `Mismatched closing '${name}', expected '${frame.block.type}'`,
+          position,
+        );
+      }
+      stack.pop();
+      target = frame.parent;
+      continue;
+    }
+
+    if (!content) {
+      throw templateError("Interpolation requires a path", position);
+    }
+    target.push({ type: "value", path: content, escaped: true, position });
+  }
+
+  const unclosed = stack.at(-1)?.block;
+  if (unclosed) {
+    throw templateError(`Unclosed block '${unclosed.type}'`, unclosed.position);
+  }
+
+  return root;
+}
+
+function getPath(value: unknown, path: string): { found: boolean; value: unknown } {
+  let current = value;
+
+  for (const segment of path.split(".")) {
+    if (
+      current === null ||
+      current === undefined ||
+      (typeof current !== "object" && typeof current !== "function") ||
+      !Object.prototype.hasOwnProperty.call(current, segment)
+    ) {
+      return { found: false, value: undefined };
+    }
+    current = (current as Record<string, unknown>)[segment];
+  }
+
+  return { found: true, value: current };
+}
+
+function resolve(path: string, context: Context): unknown {
+  if (path === "this") {
+    return context.current;
+  }
+  if (path.startsWith("this.")) {
+    return getPath(context.current, path.slice(5)).value;
+  }
+  if (path === "@index") {
+    return context.inEach ? context.index : undefined;
+  }
+
+  if (context.inEach) {
+    const local = getPath(context.current, path);
+    if (local.found) {
+      return local.value;
+    }
+  }
+  return getPath(context.root, path).value;
+}
+
+function isTruthy(value: unknown): boolean {
+  if (Array.isArray(value)) {
+    return value.length > 0;
+  }
+  return !(
+    value === "" ||
+    value === 0 ||
+    value === 0n ||
+    value === false ||
+    value === null ||
+    value === undefined
+  );
+}
+
+function scalarText(value: unknown, position: Position): string {
+  if (value === null || value === undefined) {
+    return "";
+  }
+  if (
+    typeof value === "string" ||
+    typeof value === "number" ||
+    typeof value === "bigint" ||
+    typeof value === "boolean"
+  ) {
+    return String(value);
+  }
+  throw templateError(`Cannot render value of type '${typeof value}' as text`, position);
+}
+
+function escapeHtml(value: string): string {
+  return value.replace(/[&<>"']/g, (character) => {
+    switch (character) {
+      case "&":
+        return "&amp;";
+      case "<":
+        return "&lt;";
+      case ">":
+        return "&gt;";
+      case '"':
+        return "&quot;";
+      default:
+        return "&#39;";
+    }
+  });
+}
+
+function renderNodes(nodes: Node[], context: Context): string {
+  let output = "";
+
+  for (const node of nodes) {
+    if (node.type === "text") {
+      output += node.value;
+      continue;
+    }
+
+    if (node.type === "value") {
+      const text = scalarText(resolve(node.path, context), node.position);
+      output += node.escaped ? escapeHtml(text) : text;
+      continue;
+    }
+
+    const value = resolve(node.path, context);
+    if (node.type === "if") {
+      output += renderNodes(isTruthy(value) ? node.body : node.alternate, context);
+      continue;
+    }
+
+    if (!Array.isArray(value) || value.length === 0) {
+      output += renderNodes(node.alternate, context);
+      continue;
+    }
+
+    for (let index = 0; index < value.length; index++) {
+      output += renderNodes(node.body, {
+        root: context.root,
+        current: value[index],
+        index,
+        inEach: true,
+      });
+    }
+  }
+
+  return output;
+}
+
+export function render(template: string, data: unknown): string {
+  return renderNodes(parse(template), {
+    root: data,
+    current: data,
+    inEach: false,
+  });
+}

